const fs = require('node:fs');
const path = require('node:path');
const { DatabaseSync } = require('node:sqlite');

function uniqueTags(tags) {
  const result = [];
  const seen = new Set();
  for (const value of Array.isArray(tags) ? tags : []) {
    const tag = String(value).trim();
    const key = tag.toLocaleLowerCase();
    if (tag && !seen.has(key)) {
      seen.add(key);
      result.push(tag.slice(0, 60));
    }
  }
  return result;
}

function hydrate(row) {
  if (!row) return null;
  return {
    id: row.id,
    url: row.url,
    canonicalUrl: row.canonical_url,
    title: row.title,
    description: row.description,
    source: row.source,
    tags: JSON.parse(row.tags_json),
    readLater: Boolean(row.read_later),
    createdAt: row.created_at,
    updatedAt: row.updated_at
  };
}

class BookmarkStore {
  constructor(dbPath) {
    if (dbPath !== ':memory:') fs.mkdirSync(path.dirname(dbPath), { recursive: true });
    this.db = new DatabaseSync(dbPath);
    this.db.exec(`
      PRAGMA journal_mode = WAL;
      CREATE TABLE IF NOT EXISTS bookmarks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        url TEXT NOT NULL,
        canonical_url TEXT NOT NULL UNIQUE,
        title TEXT NOT NULL,
        description TEXT NOT NULL DEFAULT '',
        source TEXT NOT NULL,
        tags_json TEXT NOT NULL DEFAULT '[]',
        read_later INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
    `);
  }

  all() {
    return this.db.prepare('SELECT * FROM bookmarks ORDER BY created_at DESC, id DESC').all().map(hydrate);
  }

  get(id) {
    return hydrate(this.db.prepare('SELECT * FROM bookmarks WHERE id = ?').get(id));
  }

  findByCanonical(canonicalUrl, excludingId = null) {
    const row = excludingId === null
      ? this.db.prepare('SELECT * FROM bookmarks WHERE canonical_url = ?').get(canonicalUrl)
      : this.db.prepare('SELECT * FROM bookmarks WHERE canonical_url = ? AND id != ?').get(canonicalUrl, excludingId);
    return hydrate(row);
  }

  create(input) {
    const now = new Date().toISOString();
    const result = this.db.prepare(`
      INSERT INTO bookmarks (url, canonical_url, title, description, source, tags_json, read_later, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      input.url,
      input.canonicalUrl,
      input.title,
      input.description || '',
      input.source,
      JSON.stringify(uniqueTags(input.tags)),
      input.readLater ? 1 : 0,
      now,
      now
    );
    return this.get(Number(result.lastInsertRowid));
  }

  update(id, input) {
    const now = new Date().toISOString();
    this.db.prepare(`
      UPDATE bookmarks
      SET url = ?, canonical_url = ?, title = ?, description = ?, source = ?, tags_json = ?, read_later = ?, updated_at = ?
      WHERE id = ?
    `).run(
      input.url,
      input.canonicalUrl,
      input.title,
      input.description || '',
      input.source,
      JSON.stringify(uniqueTags(input.tags)),
      input.readLater ? 1 : 0,
      now,
      id
    );
    return this.get(id);
  }

  delete(id) {
    return this.db.prepare('DELETE FROM bookmarks WHERE id = ?').run(id).changes > 0;
  }

  close() {
    this.db.close();
  }
}

module.exports = { BookmarkStore, uniqueTags };
function decodeEntities(value) {
  return value
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(Number.parseInt(code, 16)));
}

function cleanText(value) {
  return decodeEntities(value.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim());
}

function readMeta(html, names) {
  const tags = html.match(/<meta\s+[^>]*>/gi) || [];
  for (const tag of tags) {
    const attrs = {};
    for (const match of tag.matchAll(/([:\w-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)) {
      attrs[match[1].toLowerCase()] = match[2] ?? match[3] ?? match[4] ?? '';
    }
    const identity = (attrs.property || attrs.name || '').toLowerCase();
    if (names.includes(identity) && attrs.content) return cleanText(attrs.content);
  }
  return '';
}

function extractMetadata(html, address) {
  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = readMeta(html, ['og:title', 'twitter:title']) || (titleMatch ? cleanText(titleMatch[1]) : '');
  const description = readMeta(html, ['description', 'og:description', 'twitter:description']);
  const source = new URL(address).hostname.replace(/^www\./i, '');
  return { title, description, source };
}

async function fetchPageMetadata(address, fetchImpl = globalThis.fetch) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 6000);
  try {
    const response = await fetchImpl(address, {
      redirect: 'follow',
      signal: controller.signal,
      headers: {
        'accept': 'text/html,application/xhtml+xml',
        'user-agent': 'Trove Bookmark Manager/1.0'
      }
    });
    if (!response.ok) throw new Error(`Page returned ${response.status}`);
    const contentType = response.headers.get('content-type') || '';
    if (!contentType.includes('html')) throw new Error('Page is not HTML');
    const html = (await response.text()).slice(0, 1_500_000);
    return extractMetadata(html, response.url || address);
  } finally {
    clearTimeout(timeout);
  }
}

module.exports = { extractMetadata, fetchPageMetadata };
const TRACKING_KEYS = new Set([
  'fbclid',
  'gclid',
  'dclid',
  'msclkid',
  'mc_cid',
  'mc_eid'
]);

function parseWebAddress(raw) {
  if (typeof raw !== 'string' || !raw.trim()) {
    throw new TypeError('Enter a complete web address, such as https://example.com');
  }

  let url;
  try {
    url = new URL(raw.trim());
  } catch {
    throw new TypeError('Enter a complete web address, such as https://example.com');
  }

  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new TypeError('Enter a complete web address, such as https://example.com');
  }

  return url;
}

function canonicalizeAddress(raw) {
  const url = parseWebAddress(raw);
  url.hash = '';
  url.hostname = url.hostname.toLowerCase();

  for (const key of [...url.searchParams.keys()]) {
    const normalized = key.toLowerCase();
    if (normalized.startsWith('utm_') || TRACKING_KEYS.has(normalized)) {
      url.searchParams.delete(key);
    }
  }

  url.searchParams.sort();
  if (url.pathname.length > 1 && url.pathname.endsWith('/')) {
    url.pathname = url.pathname.replace(/\/+$/, '');
  }

  return url.toString();
}

module.exports = { canonicalizeAddress, parseWebAddress };
const state = {
  bookmarks: [],
  view: 'all',
  query: '',
  tag: '',
  deleteConfirmId: null,
  attentionId: null,
  editingId: null
};

